    // Chlorine data table
    await pool.query(`
      CREATE TABLE IF NOT EXISTS "chlorine_data" (
        "region" VARCHAR(100),
        "circle" VARCHAR(100),
        "division" VARCHAR(100),
        "sub_division" VARCHAR(100),
