    user: User,
    ipAddress?: string,
    userAgent?: string,
    sessionId?: string,
  ): Promise<UserLoginLog>;
  logUserLogout(sessionId: string): Promise<void>;
  getUserLoginLogs(limit?: number): Promise<UserLoginLog[]>;
  getUserLoginLogsByUserId(
    userId: number,
    limit?: number,
  ): Promise<UserLoginLog[]>;

  // User activity tracking operations
