                      lpcd_value_day5: sql`EXCLUDED.lpcd_value_day5`,
                      lpcd_value_day6: sql`EXCLUDED.lpcd_value_day6`,
                      lpcd_value_day7: sql`EXCLUDED.lpcd_value_day7`,
                      water_date_day1: sql`EXCLUDED.water_date_day1`,
