          </div>
          <span className="hidden sm:flex items-center text-xs text-blue-600 bg-blue-50 px-3 py-1 rounded-full">
            <span className="font-medium">
              {isFiltering ? geoFilteredSchemes.length : schemes.length}
            </span>
            <span className="ml-1">
