      </div>

      {/* Scheme Details Modal */}
      <SchemeDetailsModal
        scheme={selectedScheme}
        isOpen={isModalOpen}
        onClose={handleCloseModal}
      />

      {/* AI Assistant Chatbot is now managed globally in App.tsx */}
    </DashboardLayout>
  );
}

