  const messagesEndRef = React.useRef<HTMLDivElement>(null);
  const filterContext = useContext(FilterContext);

  // Auto-scroll to bottom when messages change
  React.useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages]);

  // Excel export helper function
  const triggerExcelExport = () => {
    try {
      console.log('Attempting to trigger Excel export...');

      // Find export button on current page using multiple selectors
      const exportButtonSelectors = [
        'button:has(.lucide-download)',
        'button[aria-label*="Export"]',
        'button.border-green-200',
        'button.bg-green-50',
        'button.text-green-700'
      ];

      for (const selector of exportButtonSelectors) {
        const button = document.querySelector(selector);
        if (button) {
          console.log(`Found export button with selector: ${selector}`);
          (button as HTMLButtonElement).click();
          return;
        }
      }

      // Fallback: find any button with "export" or "download" text
      const allButtons = Array.from(document.querySelectorAll('button'));
      const exportButton = allButtons.find(btn => {
        const text = btn.textContent?.toLowerCase() || '';
        return text.includes('export') && text.includes('excel');
      });

      if (exportButton) {
        console.log('Found export button by text content');
        (exportButton as HTMLButtonElement).click();
      } else {
        console.warn('No export button found on current page');
      }
    } catch (error) {
      console.error('Error triggering Excel export:', error);
    }
  };

  // Historical data export helper function
  const triggerPressureHistoricalExport = async (startDate: string, endDate: string, region?: string) => {
    try {
      console.log(`Triggering pressure historical export from ${startDate} to ${endDate} for region: ${region || 'all'}`);

      // Build query parameters for the API request
      const params = new URLSearchParams();
      params.append("startDate", startDate);
      params.append("endDate", endDate);

      if (region && region !== "all") {
        params.append("region", region);
      }

      const queryString = params.toString();
      const url = `/api/pressure/export/historical?${queryString}`;

      console.log(`Calling pressure historical export API: ${url}`);

      const response = await fetch(url);

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to export historical pressure data");
      }

      // Get the filename from response headers
      const contentDisposition = response.headers.get('content-disposition');
      let filename = `Pressure_Historical_Data_${startDate}_to_${endDate}.xlsx`;

      if (contentDisposition) {
        const filenameMatch = contentDisposition.match(/filename=(.+)/);
        if (filenameMatch) {
          filename = filenameMatch[1];
        }
      }

      // Create blob and download
      const blob = await response.blob();
      const downloadUrl = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(downloadUrl);

      console.log(`Successfully downloaded pressure historical data: ${filename}`);

    } catch (error) {
      console.error('Error exporting pressure historical data:', error);
      // Fallback to UI interaction approach
      triggerHistoricalExport(startDate, endDate, region);
    }
