      }
    } catch (error) {
      console.error('Error triggering UI-based historical export:', error);
      triggerExcelExport();
    }
  };

  // Enhanced region extraction from query with better pattern matching
  const extractRegion = (text: string): string | null => {
    // Normalize text - convert to lowercase and remove punctuation
    const normalizedText = text.toLowerCase().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, " ");

    // Expanded region mapping with alternate spellings, typos, and local language variations
    const regionMap: Record<string, string> = {
      // Standard region names
      amravati: "Amravati",
      nagpur: "Nagpur",
      nashik: "Nashik",
      nasik: "Nashik", // Common misspelling
      pune: "Pune",
      poona: "Pune", // Alternate historical name
      konkan: "Konkan",
      mumbai: "Mumbai",
      bombay: "Mumbai", // Alternate historical name
      "chhatrapati sambhajinagar": "Chhatrapati Sambhajinagar",
      sambhajinagar: "Chhatrapati Sambhajinagar",
      aurangabad: "Chhatrapati Sambhajinagar", // Historical name

      // Common word boundaries/patterns to improve accuracy
      " amravati ": "Amravati",
      " nagpur ": "Nagpur",
      " nashik ": "Nashik",
      " nasik ": "Nashik",
      " pune ": "Pune",
      " konkan ": "Konkan",
      " mumbai ": "Mumbai",

      // Prefix patterns like "in Nagpur" or "for Pune"
      "in nagpur": "Nagpur",
      "in pune": "Pune",
      "in nashik": "Nashik",
      "in amravati": "Amravati",
      "in konkan": "Konkan",
      "in mumbai": "Mumbai",
      "in aurangabad": "Chhatrapati Sambhajinagar",
      "in sambhajinagar": "Chhatrapati Sambhajinagar",

      // Hindi/Marathi transliteration variations
      "नागपूर": "Nagpur",
      "पुणे": "Pune",
      "नाशिक": "Nashik",
      "अमरावती": "Amravati",
      "कोंकण": "Konkan",
      "मुंबई": "Mumbai",
      "छत्रपती संभाजीनगर": "Chhatrapati Sambhajinagar",
      "औरंगाबाद": "Chhatrapati Sambhajinagar",
    };

    // Check for pattern like "X region" or "region of X"
    const regionPatterns = [
      /in\s+(\w+)\s+region/i,
      /(\w+)\s+region/i,
      /region\s+of\s+(\w+)/i
    ];

    for (const pattern of regionPatterns) {
      const match = normalizedText.match(pattern);
      if (match && match[1]) {
        const potentialRegion = match[1].toLowerCase();
        // Check if the matched word is a known region
        for (const [key, value] of Object.entries(regionMap)) {
          if (key.includes(potentialRegion)) {
            return value;
          }
        }
      }
    }

    // Standard inclusion check - look for region names in the text
    for (const [key, value] of Object.entries(regionMap)) {
      // Add word boundary check for better precision with short region names
      if (key.length <= 4) {
        // For short names like Pune, check for word boundaries
        const pattern = new RegExp(`\\b${key}\\b`, 'i');
        if (pattern.test(normalizedText)) {
          return value;
        }
      } else if (normalizedText.includes(key)) {
        return value;
      }
    }

    return null;
  };

  // Enhanced status extraction from query
  const extractStatus = (text: string): { status?: string; mjpCommissioned?: boolean; mjpFullyCompleted?: boolean } => {
    const normalizedText = text.toLowerCase().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, " ");

    const statusFilters: { status?: string; mjpCommissioned?: boolean; mjpFullyCompleted?: boolean } = {};

    // MJP status patterns
    if (normalizedText.includes("mjp fully completed") || normalizedText.includes("mjp complete")) {
      statusFilters.mjpFullyCompleted = true;
    }

    if (normalizedText.includes("mjp commissioned") || normalizedText.includes("mjp commission")) {
      statusFilters.mjpCommissioned = true;
    }

    // General status patterns
    if (normalizedText.includes("fully completed") || normalizedText.includes("complete")) {
      if (!statusFilters.mjpFullyCompleted) { // Only set if MJP fully completed not already set
        statusFilters.status = "fully_completed";
      }
    }

    if (normalizedText.includes("in progress") || normalizedText.includes("progress") || normalizedText.includes("ongoing")) {
      statusFilters.status = "in_progress";
    }

    if (normalizedText.includes("connected") && !normalizedText.includes("not connected") && !normalizedText.includes("disconnect")) {
      statusFilters.status = "connected";
    }

    if (normalizedText.includes("not connected") || normalizedText.includes("disconnect") || normalizedText.includes("not-connected")) {
      statusFilters.status = "not_connected";
    }

    if (normalizedText.includes("commissioned") || normalizedText.includes("commission")) {
      if (!statusFilters.mjpCommissioned) { // Only set if MJP commissioned not already set
        statusFilters.mjpCommissioned = true;
      }
    }

    return statusFilters;
  };

  // Enhanced date extraction from query
  const extractDateRange = (text: string): { startDate?: string; endDate?: string } => {
    const normalizedText = text.toLowerCase().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, " ");

    const dateRange: { startDate?: string; endDate?: string } = {};

    // Pattern 1: "from X to Y" format
    const fromToPattern = /from\s+(\d{1,2}[\s\/\-]\d{1,2}[\s\/\-]\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+\w+\s+\d{4})\s+to\s+(\d{1,2}[\s\/\-]\d{1,2}[\s\/\-]\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+\w+\s+\d{4})/i;
    const fromToMatch = text.match(fromToPattern);

    if (fromToMatch) {
      dateRange.startDate = parseDate(fromToMatch[1]);
      dateRange.endDate = parseDate(fromToMatch[2]);
      return dateRange;
    }

    // Pattern 2: "between X and Y" format
    const betweenPattern = /between\s+(\d{1,2}[\s\/\-]\d{1,2}[\s\/\-]\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+\w+\s+\d{4})\s+and\s+(\d{1,2}[\s\/\-]\d{1,2}[\s\/\-]\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+\w+\s+\d{4})/i;
    const betweenMatch = text.match(betweenPattern);

    if (betweenMatch) {
      dateRange.startDate = parseDate(betweenMatch[1]);
      dateRange.endDate = parseDate(betweenMatch[2]);
      return dateRange;
    }

    // Pattern 3: Single date mentioned - use as end date with 30 days before as start
    const singleDatePattern = /(\d{1,2}[\s\/\-]\d{1,2}[\s\/\-]\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+\w+\s+\d{4})/i;
    const singleMatch = text.match(singleDatePattern);

    if (singleMatch) {
      const endDate = parseDate(singleMatch[1]);
      if (endDate) {
        dateRange.endDate = endDate;
        // Set start date to 30 days before end date
        const endDateObj = new Date(endDate);
        endDateObj.setDate(endDateObj.getDate() - 30);
        dateRange.startDate = endDateObj.toISOString().split('T')[0];
      }
    }

    return dateRange;
  };

  // Helper function to parse various date formats
  const parseDate = (dateStr: string): string | undefined => {
    try {
      // Clean up the date string
      const cleaned = dateStr.trim().replace(/[\s\-]/g, '/');

      // Handle formats like "2nd june 2025", "9th june", etc.
      const monthNames = {
        'january': '01', 'jan': '01',
        'february': '02', 'feb': '02',
        'march': '03', 'mar': '03',
        'april': '04', 'apr': '04',
        'may': '05',
        'june': '06', 'jun': '06',
        'july': '07', 'jul': '07',
        'august': '08', 'aug': '08',
        'september': '09', 'sep': '09',
        'october': '10', 'oct': '10',
        'november': '11', 'nov': '11',
        'december': '12', 'dec': '12'
      };

      // Pattern for "2nd june 2025" format
      const monthPattern = /(\d{1,2})(?:st|nd|rd|th)?\s+(\w+)\s*(\d{4})?/i;
      const monthMatch = dateStr.match(monthPattern);

      if (monthMatch) {
        const day = monthMatch[1].padStart(2, '0');
        const monthName = monthMatch[2].toLowerCase();
        const year = monthMatch[3] || '2025'; // Default to 2025 if no year specified

        if (monthNames[monthName as keyof typeof monthNames]) {
          const month = monthNames[monthName as keyof typeof monthNames];
          return `${year}-${month}-${day}`;
        }
      }

      // Pattern for numeric dates like "2/6/2025", "02/06/2025"
      const numericPattern = /(\d{1,2})\/(\d{1,2})\/(\d{4})/;
      const numericMatch = cleaned.match(numericPattern);

      if (numericMatch) {
        const day = numericMatch[1].padStart(2, '0');
        const month = numericMatch[2].padStart(2, '0');
        const year = numericMatch[3];
        return `${year}-${month}-${day}`;
      }

      // Try to parse as a standard date
      const parsed = new Date(dateStr);
      if (!isNaN(parsed.getTime())) {
        return parsed.toISOString().split('T')[0];
      }

    } catch (error) {
      console.error('Error parsing date:', dateStr, error);
    }

    return undefined;
  };

