              {/* Example queries */}
              <div className="mb-2 flex justify-start">
                <div className="bg-gray-100 p-3 rounded-lg max-w-[90%]">
                  <p className="text-sm font-medium mb-2">Try asking me:</p>
                  <div className="flex flex-wrap gap-2">
                    <button
