                    <button
                      className="text-xs px-2 py-1 bg-blue-50 text-blue-700 rounded-md hover:bg-blue-100"
                      onClick={() =>
                        handlePredefinedQuery("How many ESRs and villages are in Nagpur region?")
                      }
                    >
                      ESRs and villages in Nagpur
                    </button>
                    <button
                      className="text-xs px-2 py-1 bg-blue-50 text-blue-700 rounded-md hover:bg-blue-100"
                      onClick={() => 
