                <rect x="0" y="0" width="190" height="170" fill="rgba(255,255,255,0.95)" stroke="#ccc" rx="5"/>
                <text x="10" y="18" fill="#000" fontSize="12" fontWeight="bold">Maharashtra Districts</text>
