                <rect x="10" y="75" width="12" height="12" fill="#4ade80"/>
                <text x="28" y="85" fill="#000" fontSize="9">≥75% (High)</text>
                <rect x="10" y="90" width="12" height="12" fill="#a3e635"/>
                <text x="28" y="100" fill="#000" fontSize="9">50-74% (Good)</text>
