                <div>
                  <span className="text-gray-500">Scheme ID:</span>{" "}
                  {selectedVillage.scheme_id}
                </div>
                <div>
                  <span className="text-gray-500">Region:</span>{" "}
                  {selectedVillage.region}
                </div>
                <div>
