                    </Alert>
                  </div>
                )}

                {excelMutation.isError && (
                  <Alert variant="destructive">
                    <XCircle className="h-4 w-4" />
                    <AlertTitle>Import Failed</AlertTitle>
                    <AlertDescription>
                      {(excelMutation.error as Error)?.message || 'An unknown error occurred'}
