  village_name: string;
  esr_name: string;
  sensor_id?: string;
  pressure_value_1?: number | null;
  pressure_date_day_1?: string | null;
  pressure_value_2?: number | null;
  pressure_date_day_2?: string | null;
  pressure_value_3?: number | null;
  pressure_date_day_3?: string | null;
  pressure_value_4?: number | null;
  pressure_date_day_4?: string | null;
  pressure_value_5?: number | null;
  pressure_date_day_5?: string | null;
  pressure_value_6?: number | null;
  pressure_date_day_6?: string | null;
  pressure_value_7?: number | null;
  pressure_date_day_7?: string | null;
  // Additional analysis fields
  number_of_consistent_zero_value_in_pressure?: number | null;
  pressure_less_than_02_bar?: number | null;
  pressure_between_02_07_bar?: number | null;
  pressure_greater_than_07_bar?: number | null;
  pressure_less_than_05_bar?: number | null;
  pressure_between_05_10_bar?: number | null;
  pressure_greater_than_10_bar?: number | null;
  // Dashboard URL for PI Vision integration
  dashboard_url?: string;
}

interface RegionData {
  region_id: number;
  region_name: string;
}

interface HistoricalPressureData {
  id: number;
  region: string;
  circle: string;
  division: string;
  sub_division: string;
  block: string;
  scheme_id: string;
  scheme_name: string;
  village_name: string;
  esr_name: string;
  measurement_date: string;
  pressure_value: number;
  upload_batch_id: string;
  dashboard_url?: string;
  recorded_at: string;
}

interface CommunicationStatus {
  id?: number;
  region: string;
  circle: string;
  division: string;
  sub_division: string;
  block: string;
  scheme_id: string;
  scheme_name: string;
  village_name: string;
  esr_name: string;
  chlorine_connected: string;
  pressure_connected: string;
  flow_meter_connected: string;
  chlorine_status: string;
  pressure_status: string;
  flow_meter_status: string;
  overall_status: string;
}

interface PressureSensorStatus {
  connected: number;
  online: number;
  offline: number;
  noWater: number;
}

interface ImportStats {
  inserted: number;
  updated: number;
  totalProcessed: number;
  timestamp: string;
  errors: number;
}

interface PressureDashboardStats {
  totalSensors: number;
  belowRangeSensors: number;
  optimalRangeSensors: number;
  aboveRangeSensors: number;
  consistentZeroSensors: number;
  consistentBelowRangeSensors: number;
  consistentOptimalSensors: number;
  consistentAboveRangeSensors: number;
  noWaterSensors: number;
  lastImport?: ImportStats;
}

type PressureRange =
  | "all"
  | "below_0.2"
  | "between_0.2_0.7"
  | "above_0.7"
  | "consistent_zero"
  | "consistent_below"
  | "consistent_optimal"
  | "consistent_above";

type SensorStatusFilter =
  | "all"
  | "connected"
  | "online"
  | "offline"
  | "noWater"
  | "withWater";

const PressureDashboard: React.FC = () => {
  const { toast } = useToast();
  const { trackPageVisit, trackDataExport, trackFilterUsage, trackDashboardAccess } = useComprehensiveActivityTracker();

  // Track page visit on component mount
  useEffect(() => {
    trackPageVisit("Pressure Dashboard");
  }, [trackPageVisit]);

  // Listen for filter changes from chatbot
  useEffect(() => {
    const handleRegionFilterChange = (event: CustomEvent) => {
      const { region } = event.detail;
      console.log("Pressure Dashboard received region filter:", region);
      setSelectedRegion(region);
    };

    const handleMjpCommissionedFilterChange = (event: CustomEvent) => {
      const { mjpCommissioned } = event.detail;
      console.log("Pressure Dashboard received MJP commissioned filter:", mjpCommissioned);
      setCommissionedFilter(mjpCommissioned ? "true" : "all");
    };

    const handleMjpFullyCompletedFilterChange = (event: CustomEvent) => {
      const { mjpFullyCompleted } = event.detail;
      console.log("Pressure Dashboard received MJP fully completed filter:", mjpFullyCompleted);
      setFullyCompletedFilter(mjpFullyCompleted ? "true" : "all");
    };

    const handleStatusFilterChange = (event: CustomEvent) => {
      const { status } = event.detail;
      console.log("Pressure Dashboard received status filter:", status);
      if (status === "fully_completed") {
        setSchemeStatusFilter("Fully Completed");
      } else if (status === "in_progress") {
        setSchemeStatusFilter("In Progress");
      } else if (status === "connected") {
        setSchemeStatusFilter("Connected");
      } else if (status === "not_connected") {
        setSchemeStatusFilter("Not-Connected");
      } else {
        setSchemeStatusFilter("all");
      }
    };

    window.addEventListener('regionFilterChange', handleRegionFilterChange as EventListener);
    window.addEventListener('mjpCommissionedFilterChange', handleMjpCommissionedFilterChange as EventListener);
    window.addEventListener('mjpFullyCompletedFilterChange', handleMjpFullyCompletedFilterChange as EventListener);
    window.addEventListener('statusFilterChange', handleStatusFilterChange as EventListener);

    return () => {
      window.removeEventListener('regionFilterChange', handleRegionFilterChange as EventListener);
      window.removeEventListener('mjpCommissionedFilterChange', handleMjpCommissionedFilterChange as EventListener);
      window.removeEventListener('mjpFullyCompletedFilterChange', handleMjpFullyCompletedFilterChange as EventListener);
      window.removeEventListener('statusFilterChange', handleStatusFilterChange as EventListener);
    };
  }, []);

  // Global filter state (affects both cards and table data)
  const [selectedRegion, setSelectedRegion] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [commissionedFilter, setCommissionedFilter] = useState<string>("all");
  const [fullyCompletedFilter, setFullyCompletedFilter] =
    useState<string>("all");
  const [schemeStatusFilter, setSchemeStatusFilter] = useState<string>("all");

  // Card-specific filter state (only affects table data, not card counts)
  const [selectedCardFilter, setSelectedCardFilter] = useState<PressureRange>("all");

  // Sensor status filter state
  const [sensorStatusFilter, setSensorStatusFilter] = useState<SensorStatusFilter>("all");

  // Pagination state
  const [page, setPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);

  // Selected ESR for detailed view
  const [selectedESR, setSelectedESR] = useState<PressureData | null>(null);

  // Historical data state
  const [showHistoricalData, setShowHistoricalData] = useState(false);
  const [historicalStartDate, setHistoricalStartDate] = useState(() => {
    const date = new Date();
    date.setDate(date.getDate() - 30); // Default to 30 days ago
    return date.toISOString().split('T')[0];
  });
  const [historicalEndDate, setHistoricalEndDate] = useState(() => {
    const date = new Date();
    return date.toISOString().split('T')[0];
  });

  // Fetch all pressure data
  const {
    data: allPressureData = [],
    isLoading: isLoadingPressure,
    error: pressureError,
    refetch,
  } = useQuery<PressureData[]>({
    queryKey: ["/api/pressure", selectedRegion],
    queryFn: async () => {
      const params = new URLSearchParams();

      if (selectedRegion && selectedRegion !== "all") {
        params.append("region", selectedRegion);
      }

      // Note: we're not applying currentFilter here anymore
      // This ensures we get all data for the selected region
      // and will filter in the UI instead

      const queryString = params.toString();
      const url = `/api/pressure${queryString ? `?${queryString}` : ""}`;

      console.log("Fetching pressure data with URL:", url);
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error("Failed to fetch pressure data");
      }

      const data = await response.json();
      console.log(
        `Received ${data.length} pressure records for region: ${selectedRegion}`,
      );
      return data;
    },
  });

  // Fetch dashboard stats
  const { data: dashboardStats, isLoading: isLoadingStats } =
    useQuery<PressureDashboardStats>({
      queryKey: ["/api/pressure/dashboard-stats", selectedRegion],
      queryFn: async () => {
        const params = new URLSearchParams();

        if (selectedRegion && selectedRegion !== "all") {
          params.append("region", selectedRegion);
        }

        const queryString = params.toString();
        const url = `/api/pressure/dashboard-stats${queryString ? `?${queryString}` : ""}`;

        const response = await fetch(url);
        if (!response.ok) {
          throw new Error("Failed to fetch dashboard stats");
        }

        return response.json();
      },
    });

  // Fetch region data
  const { data: regionsData = [], isLoading: isLoadingRegions } = useQuery<
    RegionData[]
  >({
    queryKey: ["/api/regions"],
  });

  // Fetch communication status data
  const {
    data: communicationStatusData = [],
    isLoading: communicationStatusLoading,
    error: communicationStatusError,
  } = useQuery<CommunicationStatus[]>({
    queryKey: ["/api/communication-status/schemes"],
  });

  // Fetch pressure sensors with no water data
  const { data: noWaterSensorsData } = useQuery<{
    totalNoWaterSensors: number;
    noWaterSensors: Array<{
      region: string;
      circle: string;
      division: string;
      sub_division: string;
      block: string;
      scheme_id: string;
      scheme_name: string;
      village_name: string;
      esr_name: string;
      water_date_day7: string | null;
      water_value_day7: number | null;
      pressure_connected: string | null;
    }>;
  }>({
    queryKey: ["/api/pressure/no-water-sensors", selectedRegion],
    queryFn: async () => {
      const params = new URLSearchParams();

      if (selectedRegion && selectedRegion !== "all") {
        params.append("region", selectedRegion);
      }

      const queryString = params.toString();
      const url = `/api/pressure/no-water-sensors${queryString ? `?${queryString}` : ""}`;

      const response = await fetch(url);
      if (!response.ok) {
        throw new Error("Failed to fetch pressure sensors with no water");
      }

      const result = await response.json();
      console.log(`Received pressure no water sensors data:`, result);
      return result.data;
    },
  });

  // Fetch pressure sensors with water data
  const { data: withWaterSensorsData } = useQuery<{
    totalWithWaterSensors: number;
    withWaterSensors: Array<{
      region: string;
      circle: string;
      division: string;
      sub_division: string;
      block: string;
      scheme_id: string;
      scheme_name: string;
      village_name: string;
      esr_name: string;
      water_date_day7: string | null;
      water_value_day7: number | null;
      pressure_connected: string | null;
    }>;
  }>({
    queryKey: ["/api/pressure/with-water-sensors", selectedRegion],
    queryFn: async () => {
      const params = new URLSearchParams();

      if (selectedRegion && selectedRegion !== "all") {
        params.append("region", selectedRegion);
      }

      const queryString = params.toString();
      const url = `/api/pressure/with-water-sensors${queryString ? `?${queryString}` : ""}`;

      const response = await fetch(url);
      if (!response.ok) {
        throw new Error("Failed to fetch pressure sensors with water");
      }

      const result = await response.json();
      console.log(`Received pressure with water sensors data:`, result);
      return result.data;
    },
  });

  // Fetch scheme status data for filtering
  const { data: schemeStatusData = [], isLoading: isLoadingSchemeStatus } =
    useQuery<any[]>({
      queryKey: ["/api/schemes", selectedRegion],
      queryFn: async () => {
        const params = new URLSearchParams();

        if (selectedRegion && selectedRegion !== "all") {
          params.append("region", selectedRegion);
        }

        const queryString = params.toString();
        const url = `/api/schemes${queryString ? `?${queryString}` : ""}`;

        console.log("Fetching scheme status data with URL:", url);
        const response = await fetch(url);
        if (!response.ok) {
          throw new Error("Failed to fetch scheme status data");
        }

        const data = await response.json();
        console.log(`Received ${data.length} scheme status records`);
        return data;
      },
    });

  // Fetch historical pressure data when dates change
  const {
    data: historicalPressureData = [],
    isLoading: isLoadingHistorical,
    error: historicalError,
    refetch: refetchHistorical,
  } = useQuery<HistoricalPressureData[]>({
    queryKey: ["/api/pressure/historical", historicalStartDate, historicalEndDate, selectedRegion],
    queryFn: async () => {
      const params = new URLSearchParams();
      params.append("startDate", historicalStartDate);
      params.append("endDate", historicalEndDate);

      if (selectedRegion && selectedRegion !== "all") {
        params.append("region", selectedRegion);
      }

      const queryString = params.toString();
      const url = `/api/pressure/historical?${queryString}`;

      const response = await fetch(url);
      if (!response.ok) {
        throw new Error("Failed to fetch historical pressure data");
      }

      const result = await response.json();
      return result || [];
    },
    enabled: showHistoricalData, // Only fetch when historical view is enabled
  });

  // Get current pressure value (day 7 only - no fallback to previous days)
  const getCurrentPressureValue = (data: PressureData): number | null => {
    // Only use the current day (day 7) value - if it's null/blank, return null
    const currentValue = data.pressure_value_7;
    if (
      currentValue !== undefined &&
      currentValue !== null &&
      String(currentValue) !== "" &&
      !isNaN(Number(currentValue))
    ) {
      return Number(currentValue);
    }
    return null;
  };

  // Calculate sensor status counts for pressure sensors
  const calculatePressureSensorStatus = useMemo((): PressureSensorStatus => {
    const status = { connected: 0, online: 0, offline: 0, noWater: 0 };

    if (!allPressureData || !communicationStatusData) {
      return status;
    }

    // Create a map of the full hierarchy from pressure data for exact matching
    const pressureLocationKeys = new Set(
      allPressureData.map(item => 
        `${item.region}|${item.circle}|${item.division}|${item.sub_division}|${item.block}|${item.village_name}|${item.esr_name}`
      )
    );

    // Filter communication status for regions if selected
    const filteredCommStatus = selectedRegion === "all" 
      ? communicationStatusData 
      : communicationStatusData.filter(comm => comm.region === selectedRegion);

    // Use Sets to track unique ESR names to avoid double counting
    const uniqueConnectedESRs = new Set<string>();
    const uniqueOnlineESRs = new Set<string>();
    const uniqueOfflineESRs = new Set<string>();

    filteredCommStatus.forEach(commStatus => {
      // Create the location key for this communication status record
      const commLocationKey = `${commStatus.region}|${commStatus.circle}|${commStatus.division}|${commStatus.sub_division}|${commStatus.block}|${commStatus.village_name}|${commStatus.esr_name}`;

      // Only count if this exact location hierarchy has pressure data
      if (pressureLocationKeys.has(commLocationKey)) {
        // Count connected sensors (match exact database values)
        if (commStatus.pressure_connected === 'Connected') {
          uniqueConnectedESRs.add(commLocationKey);

          // Count online/offline status for connected sensors (match exact database values)
          if (commStatus.pressure_status === 'Online') {
            uniqueOnlineESRs.add(commLocationKey);
          } else if (commStatus.pressure_status === 'Offline') {
            uniqueOfflineESRs.add(commLocationKey);
          }
        }
      }
    });

    status.connected = uniqueConnectedESRs.size;
    status.online = uniqueOnlineESRs.size;
    status.offline = uniqueOfflineESRs.size;

    // Use the no water sensors data from the API
    status.noWater = noWaterSensorsData?.totalNoWaterSensors || 0;

    return status;
  }, [allPressureData, communicationStatusData, selectedRegion, noWaterSensorsData]);

  // Get the CSS class and status text based on pressure value
  const getPressureStatusInfo = (value: number | null) => {
    if (value === null)
      return { className: "bg-gray-100", statusText: "No Data" };

    if (value < 0.2)
      return {
        className: "bg-red-50 border-red-200",
        statusText: "Below Range",
        textColor: "text-red-800",
        icon: <AlertTriangle className="h-5 w-5 text-red-600" />,
      };

    if (value >= 0.2 && value <= 0.7)
      return {
        className: "bg-green-50 border-green-200",
        statusText: "Optimal",
        textColor: "text-green-800",
        icon: <CheckCircle className="h-5 w-5 text-green-600" />,
      };

    return {
      className: "bg-orange-50 border-orange-200",
      statusText: "Above Range",
      textColor: "text-orange-800",
      icon: <AlertCircle className="h-5 w-5 text-orange-600" />,
    };
  };

  // Handler for commissioned filter changes
  const handleCommissionedFilterChange = (value: string) => {
    setCommissionedFilter(value);

    // Track filter usage
    if (value !== "all") {
      trackFilterUsage("commissioned", value, undefined, "pressure_dashboard");
    }

    // If "Not Commissioned", reset and disable "Fully Completed" filter
    if (value === "No") {
      setFullyCompletedFilter("all");
    }

    // Reset page to 1 when filter changes
    setPage(1);
  };

  // Handler for fully completed filter changes
  const handleFullyCompletedFilterChange = (value: string) => {
    setFullyCompletedFilter(value);

    // Track filter usage
    if (value !== "all") {
      trackFilterUsage("fullyCompleted", value, undefined, "pressure_dashboard");
    }

    // If "Fully Completed", set "Commissioned" to "Yes"
    if (value === "Fully Completed") {
      setCommissionedFilter("Yes");
    }

    // Reset page to 1 when filter changes
    setPage(1);
  };

  // Handler for scheme status filter changes
  const handleSchemeStatusFilterChange = (value: string) => {
    setSchemeStatusFilter(value);

    // Track filter usage
    if (value !== "all") {
      trackFilterUsage("schemeStatus", value, undefined, "pressure_dashboard");
    }

    // Reset page to 1 when filter changes
    setPage(1);
  };

  // Handler for sensor status card clicks
  const handleSensorStatusClick = (status: SensorStatusFilter) => {
    if (sensorStatusFilter === status) {
      // If same filter is clicked, clear the filter
      setSensorStatusFilter("all");
    } else {
      // Apply the new filter
      setSensorStatusFilter(status);
    }

    // Track filter usage
    trackFilterUsage("sensor_status", status, undefined, "pressure_dashboard");

    // Reset page to 1 when filter changes
    setPage(1);
  };

  // Track page visit on component mount
  useEffect(() => {
    trackPageVisit("Pressure Dashboard");
  }, [trackPageVisit]);

  // Create scheme status map
  const schemeStatusMap = useMemo(() => {
    const map = new Map();
    if (schemeStatusData && schemeStatusData.length > 0) {
      schemeStatusData.forEach((status) => {
        map.set(status.scheme_id, status);
      });
    }
    return map;
  }, [schemeStatusData]);

  // Calculate local dashboard stats based on filtered data
  const calculateLocalDashboardStats = (data: PressureData[]): PressureDashboardStats => {
    const stats: PressureDashboardStats = {
      totalSensors: data.length,
      belowRangeSensors: 0,
      optimalRangeSensors: 0,
      aboveRangeSensors: 0,
      consistentZeroSensors: 0,
      consistentBelowRangeSensors: 0,
      consistentOptimalSensors: 0,
      consistentAboveRangeSensors: 0,
      noWaterSensors: 0
    };

    // Count by category
    data.forEach(item => {
      const latestValue = getCurrentPressureValue(item);

      // Treat null/blank current values as "below range" 
      if (latestValue === null) {
        stats.belowRangeSensors++;
      } else if (latestValue < 0.2 && latestValue >= 0) {
        stats.belowRangeSensors++;
      } else if (latestValue >= 0.2 && latestValue <= 0.7) {
        stats.optimalRangeSensors++;
      } else if (latestValue > 0.7) {
        stats.aboveRangeSensors++;
      }

      // Count consistent readings
      if ((item.number_of_consistent_zero_value_in_pressure || 0) === 7) {
        stats.consistentZeroSensors++;
      }

      const values = [
        parseFloat(String(item.pressure_value_1 || 0)),
        parseFloat(String(item.pressure_value_2 || 0)),
        parseFloat(String(item.pressure_value_3 || 0)),
        parseFloat(String(item.pressure_value_4 || 0)),
        parseFloat(String(item.pressure_value_5 || 0)),
        parseFloat(String(item.pressure_value_6 || 0)),
        parseFloat(String(item.pressure_value_7 || 0)),
      ];

      if (values.every(val => val > 0 && val < 0.2)) {
        stats.consistentBelowRangeSensors++;
      } else if (values.every(val => val >= 0.2 && val <= 0.7)) {
        stats.consistentOptimalSensors++;
      } else if (values.every(val => val > 0.7)) {
        stats.consistentAboveRangeSensors++;
      }
    });

    // Preserve import statistics if available
    if (dashboardStats?.lastImport) {
      stats.lastImport = dashboardStats.lastImport;
    }

    return stats;
  };

  // Apply global filters to data for both cards and table
  const globallyFilteredData = useMemo(() => {
    let filtered = [...allPressureData];

    // Apply search filter if query exists
    if (searchQuery.trim() !== "") {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(
        (item) =>
          item.scheme_name?.toLowerCase().includes(query) ||
          item.region?.toLowerCase().includes(query) ||
          item.village_name?.toLowerCase().includes(query) ||
          item.esr_name?.toLowerCase().includes(query),
      );
    }

    // Double-check region filtering to ensure only data from selected region is shown
    if (selectedRegion && selectedRegion !== "all") {
      filtered = filtered.filter((item) => item.region === selectedRegion);
    }

    // Apply sensor status filter
    if (sensorStatusFilter !== "all") {
      // Create a map of ESR location keys to their communication status
      const commStatusMap = new Map<string, CommunicationStatus>();
      communicationStatusData?.forEach(status => {
        const key = `${status.region}|${status.circle}|${status.division}|${status.sub_division}|${status.block}|${status.village_name}|${status.esr_name}`;
        commStatusMap.set(key, status);
      });

      filtered = filtered.filter(item => {
        const key = `${item.region}|${item.circle}|${item.division}|${item.sub_division}|${item.block}|${item.village_name}|${item.esr_name}`;
        const commStatus = commStatusMap.get(key);

        if (!commStatus) return false;

        switch (sensorStatusFilter) {
          case "connected":
            return commStatus.pressure_connected === 'Connected';
          case "online":
            return commStatus.pressure_connected === 'Connected' && commStatus.pressure_status === 'Online';
          case "offline":
            return commStatus.pressure_connected === 'Connected' && commStatus.pressure_status === 'Offline';
          case "noWater":
            // Check if this ESR is in the no-water sensors list
            if (noWaterSensorsData?.noWaterSensors) {
              return noWaterSensorsData.noWaterSensors.some(sensor => 
                sensor.region === item.region &&
                sensor.circle === item.circle &&
                sensor.division === item.division &&
                sensor.sub_division === item.sub_division &&
                sensor.block === item.block &&
                sensor.scheme_id === item.scheme_id &&
                sensor.village_name === item.village_name &&
                sensor.esr_name === item.esr_name
              );
            }
            return false;
          default:
            return true;
        }
      });
    }

    // Create a map of scheme IDs to their scheme status data for filtering
    const schemeStatusMap = new Map();
    if (schemeStatusData && schemeStatusData.length > 0) {
      schemeStatusData.forEach((status) => {
        schemeStatusMap.set(status.scheme_id, status);
      });
    }

    // Apply commissioned status filter
    if (commissionedFilter !== "all") {
      filtered = filtered.filter((item) => {
        // Get scheme status from the map using scheme_id
        const status = schemeStatusMap.get(item.scheme_id);
        return status && status.mjp_commissioned === commissionedFilter;
      });
    }

    // Apply fully completed filter
    if (fullyCompletedFilter !== "all") {
      filtered = filtered.filter((item) => {
        // Get scheme status from the map using scheme_id
        const status = schemeStatusMap.get(item.scheme_id);
        return status && status.mjp_fully_completed === fullyCompletedFilter;
      });
    }

    // Apply scheme status filter
    if (schemeStatusFilter !== "all") {
      filtered = filtered.filter((item) => {
        // Get scheme status from the map using scheme_id
        const status = schemeStatusMap.get(item.scheme_id);
        if (!status) return false;

        if (schemeStatusFilter === "Connected") {
          return status.fully_completion_scheme_status !== "Not-Connected";
        }
        return status.fully_completion_scheme_status === schemeStatusFilter;
      });
    }

    return filtered;
  }, [allPressureData, selectedRegion, searchQuery, commissionedFilter, fullyCompletedFilter, schemeStatusFilter, schemeStatusData, sensorStatusFilter, communicationStatusData]);

  // Calculate card statistics based on the globally filtered data
  const cardStats = useMemo(() => {
    return calculateLocalDashboardStats(globallyFilteredData);
  }, [globallyFilteredData]);

  // Apply card selection filter for table display only
  const filteredData = useMemo(() => {
    let filtered = [...globallyFilteredData];
    if (selectedCardFilter !== "all") {
      switch (selectedCardFilter) {
        case "below_0.2":
          filtered = filtered.filter((item) => {
            const latestValue = getCurrentPressureValue(item);
            // Include null values (blank current day) and values < 0.2
            return latestValue === null || (latestValue !== null && latestValue < 0.2 && latestValue >= 0);
          });
          break;
        case "between_0.2_0.7":
          filtered = filtered.filter((item) => {
            const latestValue = getCurrentPressureValue(item);
            return latestValue !== null && latestValue >= 0.2 && latestValue <= 0.7;
          });
          break;
        case "above_0.7":
          filtered = filtered.filter((item) => {
            const latestValue = getCurrentPressureValue(item);
            return latestValue !== null && latestValue > 0.7;
          });
          break;
        case "consistent_zero":
          filtered = filtered.filter((item) => {
            return (item.number_of_consistent_zero_value_in_pressure || 0) === 7;
          });
          break;
        case "consistent_below":
          // ESRs with consistent below range pressure (<0.2 bar) for 7 days
          filtered = filtered.filter((item) => {
            const values = [
              parseFloat(String(item.pressure_value_1 || 0)),
              parseFloat(String(item.pressure_value_2 || 0)),
              parseFloat(String(item.pressure_value_3 || 0)),
              parseFloat(String(item.pressure_value_4 || 0)),
              parseFloat(String(item.pressure_value_5 || 0)),
              parseFloat(String(item.pressure_value_6 || 0)),
              parseFloat(String(item.pressure_value_7 || 0)),
            ];
            return values.every(val => val > 0 && val < 0.2);
          });
          break;
        case "consistent_optimal":
          // ESRs with consistent optimal range pressure (0.2-0.7 bar) for 7 days
          filtered = filtered.filter((item) => {
            const values = [
              parseFloat(String(item.pressure_value_1 || 0)),
              parseFloat(String(item.pressure_value_2 || 0)),
              parseFloat(String(item.pressure_value_3 || 0)),
              parseFloat(String(item.pressure_value_4 || 0)),
              parseFloat(String(item.pressure_value_5 || 0)),
              parseFloat(String(item.pressure_value_6 || 0)),
              parseFloat(String(item.pressure_value_7 || 0)),
            ];
            return values.every(val => val >= 0.2 && val <= 0.7);
          });
          break;
        case "consistent_above":
          // ESRs with consistent above range pressure (>0.7 bar) for 7 days
          filtered = filtered.filter((item) => {
            const values = [
              parseFloat(String(item.pressure_value_1 || 0)),
              parseFloat(String(item.pressure_value_2 || 0)),
              parseFloat(String(item.pressure_value_3 || 0)),
              parseFloat(String(item.pressure_value_4 || 0)),
              parseFloat(String(item.pressure_value_5 || 0)),
              parseFloat(String(item.pressure_value_6 || 0)),
              parseFloat(String(item.pressure_value_7 || 0)),
            ];
            return values.every(val => val > 0.7);
          });
          break;
      }
    }

    // Apply sensor status filter for table only
    if (sensorStatusFilter && sensorStatusFilter !== "all") {
      filtered = filtered.filter((item) => {
        const commStatus = communicationStatusData.find(
          comm => comm.region === item.region &&
                  comm.circle === item.circle &&
                  comm.division === item.division &&
                  comm.sub_division === item.sub_division &&
                  comm.block === item.block &&
                  comm.village_name === item.village_name &&
                  comm.esr_name === item.esr_name
        );

        if (!commStatus) return false;

        if (sensorStatusFilter === "connected") {
          return commStatus.pressure_connected === "Connected";
        } else if (sensorStatusFilter === "online") {
          return commStatus.pressure_connected === "Connected" && 
                 commStatus.pressure_status === "Online";
        } else if (sensorStatusFilter === "offline") {
          return commStatus.pressure_connected === "Connected" && 
                 commStatus.pressure_status === "Offline";
        } else if (sensorStatusFilter === "noWater") {
          // Check if this ESR is in the no-water sensors list
          if (noWaterSensorsData?.noWaterSensors) {
            return noWaterSensorsData.noWaterSensors.some(sensor => 
              sensor.region === item.region &&
              sensor.circle === item.circle &&
              sensor.division === item.division &&
              sensor.sub_division === item.sub_division &&
              sensor.block === item.block &&
              sensor.scheme_id === item.scheme_id &&
              sensor.village_name === item.village_name &&
              sensor.esr_name === item.esr_name
            );
          }
          return false;
        } else if (sensorStatusFilter === "withWater") {
          // Check if this ESR is in the with-water sensors list
          if (withWaterSensorsData?.withWaterSensors) {
            return withWaterSensorsData.withWaterSensors.some(sensor => 
              sensor.region === item.region &&
              sensor.circle === item.circle &&
              sensor.division === item.division &&
              sensor.sub_division === item.sub_division &&
              sensor.block === item.block &&
              sensor.scheme_id === item.scheme_id &&
              sensor.village_name === item.village_name &&
              sensor.esr_name === item.esr_name
            );
          }
          return false;
        }

        return false;
      });
    }

    return filtered;
  }, [
    allPressureData,
    searchQuery,
    selectedRegion,
    commissionedFilter,
    fullyCompletedFilter,
    schemeStatusFilter,
    schemeStatusData,
    selectedCardFilter,
    sensorStatusFilter,
    communicationStatusData,
    noWaterSensorsData, // Add this dependency for noWater filtering
    withWaterSensorsData, // Add this dependency for withWater filtering
  ]);

  // Calculate pagination
  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = useMemo(() => {
    const startIndex = (page - 1) * itemsPerPage;
    return filteredData.slice(startIndex, startIndex + itemsPerPage);
  }, [filteredData, page, itemsPerPage]);

  // Update card values to use the globally filtered data (before card-specific filtering)
  const updatedCardStats = useMemo(() => {
    if (!dashboardStats) return null;

    // Start with a copy of the API stats
    const stats = {...dashboardStats};

    // Count values by category from the globally filtered data (respects all global filters)
    let totalSensors = 0;
    let belowRangeSensors = 0;
    let optimalRangeSensors = 0;
    let aboveRangeSensors = 0;
    let consistentZeroSensors = 0;
    let consistentBelowRangeSensors = 0;
    let consistentOptimalSensors = 0;
    let consistentAboveRangeSensors = 0;

    globallyFilteredData.forEach(item => {
      totalSensors++;

      const latestValue = getCurrentPressureValue(item);

      // Treat null/blank current values as "below range" 
      if (latestValue === null) {
        belowRangeSensors++;
      } else if (latestValue < 0.2 && latestValue >= 0) {
        belowRangeSensors++;
      } else if (latestValue >= 0.2 && latestValue <= 0.7) {
        optimalRangeSensors++;
      } else if (latestValue > 0.7) {
        aboveRangeSensors++;
      }

      // Count consistent readings
      if ((item.number_of_consistent_zero_value_in_pressure || 0) === 7) {
        consistentZeroSensors++;
      }

      const values = [
        parseFloat(String(item.pressure_value_1 || 0)),
        parseFloat(String(item.pressure_value_2 || 0)),
        parseFloat(String(item.pressure_value_3 || 0)),
        parseFloat(String(item.pressure_value_4 || 0)),
        parseFloat(String(item.pressure_value_5 || 0)),
        parseFloat(String(item.pressure_value_6 || 0)),
        parseFloat(String(item.pressure_value_7 || 0)),
      ];

      if (values.every(val => val > 0 && val < 0.2)) {
        consistentBelowRangeSensors++;
      } else if (values.every(val => val >= 0.2 && val <= 0.7)) {
        consistentOptimalSensors++;
      } else if (values.every(val => val > 0.7)) {
        consistentAboveRangeSensors++;
      }
    });

    return {
      ...stats,
      totalSensors,
      belowRangeSensors,
      optimalRangeSensors,
      aboveRangeSensors,
      consistentZeroSensors,
      consistentBelowRangeSensors,
      consistentOptimalSensors,
      consistentAboveRangeSensors
    };
  }, [dashboardStats, globallyFilteredData]);

  // Get status filter title
  const getFilterTitle = (filter: PressureRange) => {
    switch (filter) {
      case "below_0.2":
        return "Below Range (<0.2 bar)";
      case "between_0.2_0.7":
        return "Optimal Range (0.2-0.7 bar)";
      case "above_0.7":
        return "Above Range (>0.7 bar)";
      case "consistent_zero":
        return "Consistent Zero Pressure (7 days)";
      case "consistent_below":
        return "Consistent Below Range (7 days)";
      case "consistent_optimal":
        return "Consistent Optimal Range (7 days)";
      case "consistent_above":
        return "Consistent Above Range (7 days)";
      default:
        return "All ESRs";
    }
  };

  // Handler for dashboard card clicks
  const handleCardClick = (range: PressureRange) => {
    // Only update the selected card filter - this affects the table display
    // but not the card values which come from dashboardStats
    setSelectedCardFilter(range);
    setPage(1); // Reset to first page when filter changes
  };



  // Function to export data to Excel
  const exportToExcel = (data: PressureData[], filename: string) => {
    try {
      // Helper function to format date for better readability in Excel
      const formatDateForHeader = (dateStr: string | null | undefined) => {
        if (!dateStr) return "N/A";
        try {
          const date = new Date(dateStr);
          return date.toLocaleDateString("en-IN", {
            day: "2-digit",
            month: "short",
          });
        } catch {
          return dateStr || "N/A";
        }
      };

      // Get scheme status data for export
      const schemeStatusMap = new Map();
      if (schemeStatusData && schemeStatusData.length > 0) {
        schemeStatusData.forEach((status) => {
          schemeStatusMap.set(status.scheme_id, status);
        });
      }

      // Format data for Excel
      const worksheetData = data.map((item) => {
        const latestPressure = getCurrentPressureValue(item);
        const { statusText } = getPressureStatusInfo(latestPressure);

        // Get the latest date
        let latestDate: string | null = null;
        for (const day of [7, 6, 5, 4, 3, 2, 1]) {
          const dateKey = `pressure_date_day_${day}` as keyof PressureData;
          const dateValue = item[dateKey];
          if (dateValue && typeof dateValue === 'string') {
            latestDate = dateValue;
            break;
          }
        }

        // Get scheme status info
        const schemeStatus = schemeStatusMap.get(item.scheme_id);
        const commissioned = schemeStatus
          ? schemeStatus.mjp_commissioned
          : "N/A";
        const fullyCompleted = schemeStatus
          ? schemeStatus.mjp_fully_completed
          : "N/A";
        const schemeStatusValue = schemeStatus
          ? schemeStatus.fully_completion_scheme_status
          : "N/A";

        // Format dates for headers
        const date1 = formatDateForHeader(item.pressure_date_day_1);
        const date2 = formatDateForHeader(item.pressure_date_day_2);
        const date3 = formatDateForHeader(item.pressure_date_day_3);
        const date4 = formatDateForHeader(item.pressure_date_day_4);
        const date5 = formatDateForHeader(item.pressure_date_day_5);
        const date6 = formatDateForHeader(item.pressure_date_day_6);
        const date7 = formatDateForHeader(item.pressure_date_day_7);

        return {
          "Scheme ID": item.scheme_id,
          "Scheme Name": item.scheme_name || "N/A",
          Region: item.region || "N/A",
          Circle: item.circle || "N/A",
          Division: item.division || "N/A",
          "Sub Division": item.sub_division || "N/A",
          Block: item.block || "N/A",
          "Village Name": item.village_name || "N/A",
          "ESR Name": item.esr_name || "N/A",

          // Latest pressure value and status
          "Latest Pressure Value (bar)":
            latestPressure !== null ? latestPressure.toFixed(2) : "No data",
          "Last Updated": latestDate
            ? typeof latestDate === 'string' ? formatDateForHeader(latestDate) : 'No data'
            : "No data",
          Status: statusText,

          // Daily pressure values with date headers
          [`Pressure (${date1}) bar`]:
            item.pressure_value_1 !== null &&
            item.pressure_value_1 !== undefined
              ? Number(item.pressure_value_1).toFixed(2)
              : "N/A",
          [`Pressure (${date2}) bar`]:
            item.pressure_value_2 !== null &&
            item.pressure_value_2 !== undefined
              ? Number(item.pressure_value_2).toFixed(2)
              : "N/A",
          [`Pressure (${date3}) bar`]:
            item.pressure_value_3 !== null &&
            item.pressure_value_3 !== undefined
              ? Number(item.pressure_value_3).toFixed(2)
              : "N/A",
          [`Pressure (${date4}) bar`]:
            item.pressure_value_4 !== null &&
            item.pressure_value_4 !== undefined
              ? Number(item.pressure_value_4).toFixed(2)
              : "N/A",
          [`Pressure (${date5}) bar`]:
            item.pressure_value_5 !== null &&
            item.pressure_value_5 !== undefined
              ? Number(item.pressure_value_5).toFixed(2)
              : "N/A",
          [`Pressure (${date6}) bar`]:
            item.pressure_value_6 !== null &&
            item.pressure_value_6 !== undefined
              ? Number(item.pressure_value_6).toFixed(2)
              : "N/A",
          [`Pressure (${date7}) bar`]:
            item.pressure_value_7 !== null &&
            item.pressure_value_7 !== undefined
              ? Number(item.pressure_value_7).toFixed(2)
              : "N/A",

          // Analysis data
          "Days Below Range (<0.2 bar)": item.pressure_less_than_02_bar || 0,
          "Days Optimal Range (0.2-0.7 bar)":
            item.pressure_between_02_07_bar || 0,
          "Days Above Range (>0.7 bar)": item.pressure_greater_than_07_bar || 0,
          "Consistent Zero for 7 Days":
            item.number_of_consistent_zero_value_in_pressure === 7
              ? "Yes"
              : "No",

          // Scheme status info
          Commissioned: commissioned,
          "Fully Completed": fullyCompleted,
          "Scheme Status": schemeStatusValue,
        };
      });

      // Create worksheet
      const worksheet = XLSX.utils.json_to_sheet(worksheetData);

      // Set column widths
      const columns = [
        { wch: 12 }, // Scheme ID
        { wch: 25 }, // Scheme Name
        { wch: 12 }, // Region
        { wch: 20 }, // Village Name
        { wch: 15 }, // ESR Name
        { wch: 15 }, // Latest Pressure Value
        { wch: 15 }, // Last Updated
        { wch: 10 }, // Status
        { wch: 15 }, // Days Below Range
        { wch: 15 }, // Days Optimal Range
        { wch: 15 }, // Days Above Range
        { wch: 15 }, // Consistent Zero
        { wch: 15 }, // Commissioned
        { wch: 15 }, // Fully Completed
        { wch: 15 }, // Scheme Status
        { wch: 12 }, // Pressure Day 1
        { wch: 12 }, // Pressure Day 2
        { wch: 12 }, // Pressure Day 3
        { wch: 12 }, // Pressure Day 4
        { wch: 12 }, // Pressure Day 5
        { wch: 12 }, // Pressure Day 6
        { wch: 12 }, // Pressure Day 7
      ];
      worksheet["!cols"] = columns;

      // Create workbook and add the worksheet
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Pressure Data");

      // Add filter params to filename to make it more descriptive
      let enhancedFilename = filename;
      if (commissionedFilter !== "all") {
        enhancedFilename += `_Commissioned-${commissionedFilter}`;
      }
      if (fullyCompletedFilter !== "all") {
        enhancedFilename += `_FullyCompleted-${fullyCompletedFilter}`;
      }
      if (schemeStatusFilter !== "all") {
        enhancedFilename += `_Status-${schemeStatusFilter}`;
      }

      // Generate Excel file and trigger download
      const finalFilename = `${enhancedFilename}.xlsx`;
      XLSX.writeFile(workbook, finalFilename);

      // Track the data export activity with detailed filter information
      const appliedFilters = {
        region: selectedRegion !== "all" ? selectedRegion : undefined,
        commissioned: commissionedFilter !== "all" ? commissionedFilter : undefined,
        fullyCompleted: fullyCompletedFilter !== "all" ? fullyCompletedFilter : undefined,
        schemeStatus: schemeStatusFilter !== "all" ? schemeStatusFilter : undefined,
        cardFilter: selectedCardFilter !== "all" ? getFilterTitle(selectedCardFilter) : undefined,
        searchQuery: searchQuery.trim() ? searchQuery : undefined
      };

      // Clean up undefined values for tracking
      const cleanedFilters = Object.fromEntries(
        Object.entries(appliedFilters).filter(([_, value]) => value !== undefined)
      );

      trackDataExport(
        "Pressure Data",
        finalFilename,
        worksheetData.length,
        cleanedFilters,
        {
          exportSource: "pressure_dashboard",
          totalSensorsAvailable: allPressureData.length,
          filteredSensors: worksheetData.length
        }
      );

      toast({
        title: "Export Successful",
        description: `${worksheetData.length} records exported to Excel`,
        duration: 3000,
      });
    } catch (error) {
      console.error("Export error:", error);
      toast({
        title: "Export Failed",
        description: "Failed to export data to Excel. Please try again.",
        variant: "destructive",
      });
    }
  };

  // Handler for exporting historical pressure data
  const exportHistoricalData = async () => {
    try {
      const params = new URLSearchParams();
      params.append("startDate", historicalStartDate);
      params.append("endDate", historicalEndDate);

      // Apply all current filters to the historical export
      if (selectedRegion && selectedRegion !== "all") {
        params.append("region", selectedRegion);
      }

      if (searchQuery.trim() !== "") {
        params.append("searchQuery", searchQuery.trim());
      }

      if (commissionedFilter !== "all") {
        params.append("commissioned", commissionedFilter);
      }

      if (fullyCompletedFilter !== "all") {
        params.append("fullyCompleted", fullyCompletedFilter);
      }

      if (schemeStatusFilter !== "all") {
        params.append("schemeStatus", schemeStatusFilter);
      }

      if (selectedCardFilter !== "all") {
        params.append("pressureRange", selectedCardFilter);
      }

      const queryString = params.toString();
      const url = `/api/pressure/export/historical?${queryString}`;

      const response = await fetch(url);

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to export historical data");
      }

      // Get the filename from response headers
      const contentDisposition = response.headers.get('content-disposition');
      let filename = `Pressure_Historical_Data_${historicalStartDate}_to_${historicalEndDate}.xlsx`;

      if (contentDisposition) {
        const filenameMatch = contentDisposition.match(/filename=(.+)/);
        if (filenameMatch) {
          filename = filenameMatch[1];
        }
      }

      // Convert response to blob and trigger download
      const blob = await response.blob();
      const downloadUrl = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(downloadUrl);

      // Track the export activity
      trackDataExport(
        "Pressure Historical Data",
        filename,
        historicalPressureData.length,
        { 
          dateRange: `${historicalStartDate} to ${historicalEndDate}`,
          region: selectedRegion !== "all" ? selectedRegion : undefined 
        },
        {
          exportSource: "pressure_historical_dashboard",
          startDate: historicalStartDate,
          endDate: historicalEndDate
        }
      );

      toast({
        title: "Export Successful",
        description: `Historical pressure data exported successfully`,
        duration: 3000,
      });
    } catch (error) {
      console.error("Export error:", error);
      toast({
        title: "Export Failed",
        description: error instanceof Error ? error.message : "Failed to export historical data",
        variant: "destructive",
      });
    }
  };

  // Loading state for dashboard
  if (isLoadingPressure || isLoadingStats || isLoadingRegions) {
    return (
      <div className="container mx-auto p-4">
        {/* <h1 className="text-2xl font-bold mb-6">Pressure Monitoring Dashboard</h1> */}
        <div className="grid gap-4 md:grid-cols-4 mb-8">
          <Skeleton className="h-40 w-full" />
          <Skeleton className="h-40 w-full" />
          <Skeleton className="h-40 w-full" />
          <Skeleton className="h-40 w-full" />
        </div>
        <Skeleton className="h-96 w-full" />
      </div>
    );
  }

  // Error state
  if (pressureError) {
    return (
      <div className="container mx-auto p-4">
        <div
          className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative"
          role="alert"
        >
          <strong className="font-bold">Error: </strong>
          <span className="block sm:inline">
            Failed to load pressure data. Please try again later.
          </span>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto p-4">
      {/* Header with Date */}
      <div className="mb-6">
        <h1 className="text-3xl font-bold tracking-tight text-gray-900">
          <TranslatedText>Pressure Dashboard</TranslatedText>
        </h1>
        <p className="text-gray-500 mt-1">
          <TranslatedText>Monitor water pressure levels across water schemes and ESRs</TranslatedText>
        </p>
        <p className="text-sm text-blue-600 font-medium mt-2">
          <TranslatedText>Dashboard Updated</TranslatedText>: {new Date().toLocaleDateString('en-IN', { 
            weekday: 'long', 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric' 
          })} <TranslatedText>at</TranslatedText> {new Date().toLocaleTimeString('en-IN', { 
            hour: '2-digit', 
            minute: '2-digit' 
          })}
        </p>
      </div>

      <div className="bg-white rounded-xl shadow-sm mb-6 p-4 border border-blue-100">
        <div className="flex flex-col md:flex-row md:flex-wrap gap-4 items-start md:items-end">
          {/* Select Region */}
          <div className="w-full md:w-64">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Select Region
            </label>
            <Select
              value={selectedRegion}
              onValueChange={(value) => {
                setSelectedRegion(value);
                setPage(1);
              }}
            >
              <SelectTrigger className="bg-white border border-blue-200 shadow-sm focus:ring-blue-500 focus:border-blue-500 h-10">
                <SelectValue placeholder="All Regions" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all" className="font-medium">
                  All Regions
                </SelectItem>
                <div className="h-px bg-gray-200 my-1"></div>
                {regionsData.map((region) => (
                  <SelectItem key={region.region_id} value={region.region_name}>
                    {region.region_name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Search ESRs */}
          <div className="w-full md:w-96">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Search ESRs
            </label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 h-4 w-4 text-gray-400 -translate-y-1/2" />
              <Input
                placeholder="Search by scheme, village or ESR name..."
                className="pl-9 pr-4 py-2 border-blue-200 focus:ring-blue-500 focus:border-blue-500 h-10"
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  setPage(1);
                }}
              />
              {searchQuery && (
                <button
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  onClick={() => setSearchQuery("")}
                >
                  <X className="h-4 w-4" />
                </button>
              )}
            </div>
          </div>

          {/* MJP Civil Status */}
          <div className="w-full sm:w-80">
            <div className="border border-blue-100 rounded-lg p-3 bg-blue-50 shadow-inner">
              <h3 className="text-sm font-semibold text-blue-800 mb-2 text-center tracking-wide">
                MJP Civil Status
              </h3>

              {/* Commissioned Filter */}
              <Select
                value={commissionedFilter}
                onValueChange={(value) => {
                  setCommissionedFilter(value);
                  setPage(1);
                }}
              >
                <SelectTrigger className="w-full mb-3 bg-white border border-blue-200 shadow-sm h-10">
                  <SelectValue placeholder="Scheme Readiness" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Scheme Readiness</SelectItem>
                  <SelectItem value="Yes">Commissioned</SelectItem>
                  <SelectItem value="No">Not Commissioned</SelectItem>
                </SelectContent>
              </Select>

              {/* Fully Completed Filter */}
              <Select
                value={fullyCompletedFilter}
                onValueChange={(value) => {
                  setFullyCompletedFilter(value);
                  setPage(1);
                }}
              >
                <SelectTrigger
                  className={`w-full bg-white border border-blue-200 shadow-sm h-10 ${
                    commissionedFilter === "No" ? "opacity-50" : ""
                  }`}
                >
                  <SelectValue placeholder="Scheme Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Scheme Status</SelectItem>
                  <SelectItem value="Fully Completed">
                    Fully Completed
                  </SelectItem>
                  <SelectItem value="In Progress">In Progress</SelectItem>
                </SelectContent>
              </Select>

              {commissionedFilter !== "all" && (
                <div className="mt-2 text-xs text-blue-700 text-center font-medium">
                  {
                    filteredData.filter((item) => {
                      const status = schemeStatusMap.get(item.scheme_id);
                      return (
                        status && status.mjp_commissioned === commissionedFilter
                      );
                    }).length
                  }{" "}
                  schemes
                </div>
              )}
            </div>
          </div>

          {/* Scheme Status */}
          <div className="w-full sm:w-40">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Scheme Status
            </label>
            <Select
              value={schemeStatusFilter}
              onValueChange={(value) => {
                setSchemeStatusFilter(value);
                setPage(1);
