                                    <div className="bg-blue-50/50 rounded-lg p-4 border border-blue-100">
                                      <h3 className="text-sm font-medium text-blue-800 mb-3">
                                        ESR Information
                                      </h3>

                                      <div className="space-y-3">
                                        <div className="flex justify-between items-center border-b border-blue-100 pb-2">
                                          <span className="text-sm text-blue-700">
                                            Region
                                          </span>
                                          <span className="font-medium">
                                            {selectedESR.region}
                                          </span>
                                        </div>

                                        <div className="flex justify-between items-center border-b border-blue-100 pb-2">
                                          <span className="text-sm text-blue-700">
                                            Scheme ID
                                          </span>
                                          <span className="font-medium font-mono">
                                            {selectedESR.scheme_id}
                                          </span>
                                        </div>

                                        <div className="flex justify-between items-center border-b border-blue-100 pb-2">
                                          <span className="text-sm text-blue-700">
                                            Scheme
                                          </span>
                                          <span className="font-medium">
                                            {selectedESR.scheme_name}
                                          </span>
                                        </div>

                                        <div className="flex justify-between items-center border-b border-blue-100 pb-2">
                                          <span className="text-sm text-blue-700">
                                            Village
                                          </span>
                                          <span className="font-medium">
                                            {selectedESR.village_name}
                                          </span>
                                        </div>
                                      </div>
                                    </div>

                                    <div className="bg-gradient-to-br from-blue-50 to-white rounded-lg p-4 border border-blue-100 flex flex-col">
                                      <h3 className="text-sm font-medium text-blue-800 mb-3">
                                        Current Status
                                      </h3>

                                      {(() => {
                                        const latestValue =
                                          getCurrentPressureValue(selectedESR);
                                        const statusInfo =
                                          getPressureStatusInfo(latestValue);

                                        let statusBgClass = "bg-gray-100";
                                        let statusTextClass = "text-gray-800";

                                        if (latestValue !== null) {
                                          if (latestValue < 0.2) {
                                            statusBgClass = "bg-red-100";
                                            statusTextClass = "text-red-800";
                                          } else if (
                                            latestValue >= 0.2 &&
                                            latestValue <= 0.7
                                          ) {
                                            statusBgClass = "bg-green-100";
                                            statusTextClass = "text-green-800";
                                          } else {
                                            statusBgClass = "bg-orange-100";
                                            statusTextClass = "text-orange-800";
                                          }
                                        }

                                        return (
                                          <div
                                            className={`${statusBgClass} rounded-lg p-4 flex-1 flex flex-col justify-center items-center`}
                                          >
                                            <div className="flex items-center gap-2 mb-2">
                                              {statusInfo.icon}
                                              <span
                                                className={`text-lg font-bold ${statusTextClass}`}
                                              >
                                                {statusInfo.statusText}
                                              </span>
                                            </div>

                                            <div className="text-4xl font-bold mb-2">
                                              {latestValue !== null ? (
                                                <span
                                                  className={statusTextClass}
                                                >
                                                  {latestValue.toFixed(2)}
                                                </span>
                                              ) : (
                                                "—"
                                              )}
                                            </div>

                                            <div
                                              className={`text-sm ${statusTextClass}`}
                                            >
                                              bar
                                            </div>

                                            <div className="mt-4 text-xs text-gray-600">
                                              Target Range: 0.2-0.7 bar
                                            </div>
                                          </div>
                                        );
                                      })()}
                                    </div>
                                  </div>

                                  <div className="border-t border-gray-200 pt-6">
                                    <h3 className="font-medium text-lg mb-4 text-blue-800 flex items-center gap-2">
                                      <div className="w-6 h-6 rounded-full bg-blue-100 flex items-center justify-center">
                                        <AlertCircle className="h-3 w-3 text-blue-600" />
                                      </div>
                                      7-Day Pressure History
                                    </h3>
                                    <div className="grid grid-cols-7 gap-3">
                                      {[1, 2, 3, 4, 5, 6, 7].map((day) => {
                                        const value =
                                          selectedESR[
                                            `pressure_value_${day}` as keyof PressureData
                                          ];
                                        const numValue =
                                          value !== undefined && value !== null
                                            ? Number(value)
                                            : null;
                                        const dateValue =
                                          selectedESR[
                                            `pressure_date_day_${day}` as keyof PressureData
                                          ];
                                        const { className: dayClassName } =
                                          getPressureStatusInfo(numValue);

                                        let cardBgClass =
                                          "bg-white border-gray-200";
                                        let valueTextClass = "text-gray-400";

                                        if (numValue !== null) {
                                          if (numValue < 0.2) {
                                            cardBgClass =
                                              "bg-gradient-to-br from-red-50 to-white border-red-200";
                                            valueTextClass = "text-red-600";
                                          } else if (
                                            numValue >= 0.2 &&
                                            numValue <= 0.7
                                          ) {
                                            cardBgClass =
                                              "bg-gradient-to-br from-green-50 to-white border-green-200";
                                            valueTextClass = "text-green-600";
                                          } else {
                                            cardBgClass =
                                              "bg-gradient-to-br from-orange-50 to-white border-orange-200";
                                            valueTextClass = "text-orange-600";
                                          }
                                        }

                                        return (
                                          <div
                                            key={`pressure-day-${day}`}
                                            className={`${cardBgClass} p-3 rounded-md text-center shadow-sm border relative overflow-hidden`}
                                          >
                                            <div className="relative">
                                              <p className="text-xs text-gray-700 font-medium">
                                                Day {day}
                                              </p>
                                              <p
                                                className={`text-xl font-bold ${valueTextClass}`}
                                              >
                                                {numValue !== null
                                                  ? numValue.toFixed(2)
                                                  : "—"}
                                              </p>
                                              <p className="text-xs text-gray-500 truncate">
                                                {dateValue || "No data"}
                                              </p>
                                            </div>
                                          </div>
                                        );
                                      })}
                                    </div>
                                  </div>

                                  <div className="mt-6 bg-blue-50/50 rounded-lg p-4 border border-blue-100">
                                    <h4 className="font-medium text-blue-800 mb-3">
                                      7-Day Analysis
                                    </h4>
                                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                                      <div className="bg-white p-3 rounded border border-red-100">
                                        <p className="text-sm text-red-700 mb-1">
                                          Below Range Days
                                        </p>
                                        <p className="text-xl font-bold text-red-600">
                                          {(() => {
                                            let count = 0;
                                            for (let day = 1; day <= 7; day++) {
                                              const value = selectedESR[`pressure_value_${day}` as keyof PressureData];
                                              const numValue = value !== undefined && value !== null ? Number(value) : null;
                                              if (numValue !== null && numValue >= 0 && numValue < 0.2) {
                                                count++;
                                              }
                                            }
                                            return count;
                                          })()}
                                        </p>
                                      </div>
                                      <div className="bg-white p-3 rounded border border-green-100">
                                        <p className="text-sm text-green-700 mb-1">
                                          Optimal Range Days
                                        </p>
                                        <p className="text-xl font-bold text-green-600">
                                          {(() => {
                                            let count = 0;
                                            for (let day = 1; day <= 7; day++) {
                                              const value = selectedESR[`pressure_value_${day}` as keyof PressureData];
                                              const numValue = value !== undefined && value !== null ? Number(value) : null;
                                              if (numValue !== null && numValue >= 0.2 && numValue <= 0.7) {
                                                count++;
                                              }
                                            }
                                            return count;
                                          })()}
                                        </p>
                                      </div>
                                      <div className="bg-white p-3 rounded border border-orange-100">
                                        <p className="text-sm text-orange-700 mb-1">
                                          Above Range Days
                                        </p>
                                        <p className="text-xl font-bold text-orange-600">
                                          {(() => {
                                            let count = 0;
                                            for (let day = 1; day <= 7; day++) {
                                              const value = selectedESR[`pressure_value_${day}` as keyof PressureData];
                                              const numValue = value !== undefined && value !== null ? Number(value) : null;
                                              if (numValue !== null && numValue > 0.7) {
                                                count++;
                                              }
                                            }
                                            return count;
                                          })()}
                                        </p>
                                      </div>
                                      <div className="bg-white p-3 rounded border border-gray-200">
                                        <p className="text-sm text-gray-700 mb-1">
                                          Zero Pressure Days
                                        </p>
                                        <p className="text-xl font-bold text-gray-600">
                                          {(() => {
                                            let count = 0;
                                            for (let day = 1; day <= 7; day++) {
                                              const value = selectedESR[`pressure_value_${day}` as keyof PressureData];
                                              const numValue = value !== undefined && value !== null ? Number(value) : null;
                                              if (numValue === 0) {
                                                count++;
                                              }
                                            }
                                            return count;
                                          })()}
                                        </p>
                                      </div>
                                    </div>
                                  </div>

                                  {/* PI Vision Dashboard Link */}
                                  <div className="mt-6 pt-6 border-t border-gray-200">
                                    <div className="flex justify-between items-center">
                                      <div>
                                        <h3 className="font-medium text-blue-800">
                                          PI Vision Dashboard
                                        </h3>
                                        <p className="text-sm text-gray-500">
                                          View detailed historical pressure data
                                          in PI Vision
                                        </p>
                                      </div>
                                      {selectedESR.dashboard_url ? (
                                        <Button
                                          variant="outline"
                                          className="border-blue-200 text-blue-600 hover:bg-blue-50"
                                          onClick={() =>
                                            window.open(
                                              selectedESR.dashboard_url,
                                              "_blank",
                                            )
                                          }
                                        >
                                          <Gauge className="h-4 w-4 mr-2" />{" "}
                                          Open Dashboard
                                        </Button>
                                      ) : (
                                        <Button
                                          variant="outline"
                                          disabled
                                          className="opacity-50"
                                        >
                                          <Gauge className="h-4 w-4 mr-2" />{" "}
                                          Dashboard Not Available
                                        </Button>
                                      )}
                                    </div>
                                  </div>
                                </div>
                              </>
                            )}
                          </DialogContent>
                        </Dialog>
                      </TableCell>
                    </TableRow>
                  );
                })
              ) : (
                <TableRow>
                  <TableCell
                    colSpan={8}
                    className="text-center py-8 text-gray-500"
                  >
                    {allPressureData.length === 0 ? (
                      <>No pressure data available for this region</>
                    ) : (
                      <>No results match your search criteria</>
                    )}
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </div>
      </div>

      {/* Pagination */}
      {filteredData.length > itemsPerPage && (
        <div className="flex justify-center mb-8">
          <Pagination>
            <PaginationContent>
              <PaginationItem>
                <PaginationPrevious
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    if (page > 1) setPage(page - 1);
                  }}
                  className={page === 1 ? "opacity-50 pointer-events-none" : ""}
                />
              </PaginationItem>

              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                // Logic to show 5 pages around the current page
                let pageNumber = page;
                if (page < 3) {
                  pageNumber = i + 1;
                } else if (page > totalPages - 2) {
                  pageNumber = totalPages - 4 + i;
                } else {
                  pageNumber = page - 2 + i;
                }

                // Ensure page number is within bounds
                if (pageNumber < 1) pageNumber = 1;
                if (pageNumber > totalPages) pageNumber = totalPages;

                return (
                  <PaginationItem key={`page-${pageNumber}`}>
                    <PaginationLink
                      href="#"
                      onClick={(e) => {
                        e.preventDefault();
                        setPage(pageNumber);
                      }}
                      isActive={page === pageNumber}
                    >
                      {pageNumber}
                    </PaginationLink>
                  </PaginationItem>
                );
              })}

              <PaginationItem>
                <PaginationNext
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    if (page < totalPages) setPage(page + 1);
                  }}
                  className={
                    page === totalPages ? "opacity-50 pointer-events-none" : ""
                  }
                />
              </PaginationItem>
            </PaginationContent>
          </Pagination>
        </div>
      )}
    </div>
  );
};

export default PressureDashboard;

